step3_testbench.spice:
* Testbench for BJT Parasitic RC Network
.lib "${SKY130_PDK}" tt

.param c_diff=10f c_je=5f c_cbi=2f c_cbx=2f
.param r_bb=50 r_ex=5 r_c=10 r_cc=100 r_ee=10

* DUT
CDIFF N0 N1 {c_diff}
CJE N0 N1 {c_je}
CCBI N0 N1 {c_cbi}
CCBX N0 Base {c_cbx}
rBB N1 Base {r_bb}
rEX N0 Emitter {r_ex}
rC N0 Collector {r_c}
RCC VDD Collector {r_cc}
REE Emitter GND {r_ee}

* Sources
VVDD VDD 0 DC 1.8
VBase Base 0 DC 0 AC 1 PULSE(0 1 10p 1p 1p 100p 200p)

.control
* DC Analysis
op
let dc_power = -i(VVDD) * 1.8
print dc_power

* AC Analysis
ac dec 100 1G 1000G
let gain_db = vdb(Collector)
meas ac gain_100g find gain_db at=100G

* Transient Analysis
tran 0.1p 50p
meas tran v_col_peak max v(Collector)
meas tran t_peak max_at v(Collector)

quit
.endc
.end

